package com.vocabularyai.personalization.dto;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;
import java.util.List;

/**
 * WeaknessStrengthDto
 * 
 * AI-analyzed weakness and strength detection based on learning profile
 * Generated by Gemini AI for personalized learning insights
 * 
 * Input: LearningProfileDto
 * Output: Categorized weaknesses, strengths, and priority actions
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@JsonIgnoreProperties(ignoreUnknown = true)
public class WeaknessStrengthDto {
    
    /**
     * User ID
     */
    @JsonProperty("userId")
    private Long userId;
    
    /**
     * User name
     */
    @JsonProperty("userName")
    private String userName;
    
    /**
     * Analysis timestamp
     */
    @JsonProperty("analyzedAt")
    private LocalDateTime analyzedAt;
    
    // ==================== Overall Assessment ====================
    
    /**
     * Overall learning profile summary (1-2 sentences)
     */
    @JsonProperty("profileSummary")
    private String profileSummary;
    
    /**
     * Learning style identification (VISUAL, AUDITORY, KINESTHETIC, MIXED)
     */
    @JsonProperty("learningStyle")
    private String learningStyle;
    
    /**
     * Motivation level assessment (HIGH, MEDIUM, LOW)
     */
    @JsonProperty("motivationLevel")
    private String motivationLevel;
    
    // ==================== Weaknesses ====================
    
    /**
     * List of identified weaknesses with severity and recommendations
     */
    @JsonProperty("weaknesses")
    private List<WeaknessItem> weaknesses;
    
    /**
     * Critical weaknesses requiring immediate attention (subset of weaknesses)
     */
    @JsonProperty("criticalWeaknesses")
    private List<WeaknessItem> criticalWeaknesses;
    
    /**
     * Total number of significant weaknesses
     */
    @JsonProperty("weaknessCount")
    private Integer weaknessCount;
    
    // ==================== Strengths ====================
    
    /**
     * List of identified strengths with details
     */
    @JsonProperty("strengths")
    private List<StrengthItem> strengths;
    
    /**
     * Outstanding strengths that should be leveraged
     */
    @JsonProperty("outstandingStrengths")
    private List<StrengthItem> outstandingStrengths;
    
    /**
     * Total number of identified strengths
     */
    @JsonProperty("strengthCount")
    private Integer strengthCount;
    
    // ==================== Priority Actions ====================
    
    /**
     * Prioritized action items (sorted by impact and urgency)
     */
    @JsonProperty("priorityActions")
    private List<PriorityAction> priorityActions;
    
    /**
     * Top 3 immediate next steps
     */
    @JsonProperty("immediateNextSteps")
    private List<String> immediateNextSteps;
    
    // ==================== Analysis Metadata ====================
    
    /**
     * Analysis confidence score (0-100)
     * Based on data completeness and consistency
     */
    @JsonProperty("confidenceScore")
    private Double confidenceScore;
    
    /**
     * Data quality assessment (EXCELLENT, GOOD, FAIR, POOR)
     */
    @JsonProperty("dataQuality")
    private String dataQuality;
    
    /**
     * Recommended re-analysis period in days
     */
    @JsonProperty("reanalysisPeriodDays")
    private Integer reanalysisPeriodDays;
    
    // ==================== Nested DTOs ====================
    
    /**
     * Individual weakness item
     */
    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class WeaknessItem {
        
        /**
         * Weakness category (e.g., GRAMMAR_TENSES, VOCABULARY_ADVANCED, SPEAKING_FLUENCY)
         */
        @JsonProperty("category")
        private String category;
        
        /**
         * Specific area name
         */
        @JsonProperty("area")
        private String area;
        
        /**
         * Detailed description
         */
        @JsonProperty("description")
        private String description;
        
        /**
         * Severity level (CRITICAL, HIGH, MEDIUM, LOW)
         */
        @JsonProperty("severity")
        private String severity;
        
        /**
         * Current performance percentage (0-100)
         */
        @JsonProperty("performancePercentage")
        private Double performancePercentage;
        
        /**
         * Target performance percentage (usually 80+)
         */
        @JsonProperty("targetPercentage")
        private Double targetPercentage;
        
        /**
         * Gap to close
         */
        @JsonProperty("performanceGap")
        private Double performanceGap;
        
        /**
         * Root cause analysis
         */
        @JsonProperty("rootCause")
        private String rootCause;
        
        /**
         * Suggested improvement strategies
         */
        @JsonProperty("strategies")
        private List<String> strategies;
        
        /**
         * Recommended resources/topics to focus on
         */
        @JsonProperty("focusAreas")
        private List<String> focusAreas;
        
        /**
         * Estimated time to improvement (days)
         */
        @JsonProperty("improvementTimelineDays")
        private Integer improvementTimelineDays;
    }
    
    /**
     * Individual strength item
     */
    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class StrengthItem {
        
        /**
         * Strength category
         */
        @JsonProperty("category")
        private String category;
        
        /**
         * Specific area name
         */
        @JsonProperty("area")
        private String area;
        
        /**
         * Detailed description
         */
        @JsonProperty("description")
        private String description;
        
        /**
         * Excellence level (OUTSTANDING, STRONG, SOLID)
         */
        @JsonProperty("excellenceLevel")
        private String excellenceLevel;
        
        /**
         * Current performance percentage (usually 70+)
         */
        @JsonProperty("performancePercentage")
        private Double performancePercentage;
        
        /**
         * How to leverage this strength
         */
        @JsonProperty("leverageStrategy")
        private String leverageStrategy;
        
        /**
         * Complementary skills to develop alongside this strength
         */
        @JsonProperty("relatedAreas")
        private List<String> relatedAreas;
    }
    
    /**
     * Priority action item
     */
    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class PriorityAction {
        
        /**
         * Priority rank (1=highest)
         */
        @JsonProperty("priority")
        private Integer priority;
        
        /**
         * Action description
         */
        @JsonProperty("action")
        private String action;
        
        /**
         * Why this action is important
         */
        @JsonProperty("rationale")
        private String rationale;
        
        /**
         * Expected impact on overall learning (HIGH, MEDIUM, LOW)
         */
        @JsonProperty("expectedImpact")
        private String expectedImpact;
        
        /**
         * Effort required (EASY, MODERATE, CHALLENGING)
         */
        @JsonProperty("effortLevel")
        private String effortLevel;
        
        /**
         * Timeline (e.g., "Start this week", "Focus next month")
         */
        @JsonProperty("timeline")
        private String timeline;
        
        /**
         * Related weakness/strength this addresses
         */
        @JsonProperty("addressesArea")
        private String addressesArea;
    }
}
